const p = $('Prep').first().json || {};
const r = $input.first().json || {};
const err = $('Receipt To Base64').first().json.receipt_error;

const out = (o) => [{
  json: {
    ...p,
    needs_db: false,
    action: null,
    reply: null,
    intent: 'none',
    ...o,
    route: o.needs_db === true ? 'db' : 'static'
  }
}];

const typeIt =
  'Please type it instead, e.g. "spent 250 on groceries".';

// SECURITY CHECK 1: Stop if user initialization failed.
if (p.service_error === true) {
  return out({
    intent: 'help',
    reply: 'The database is temporarily unavailable. Nothing was saved. Please try again in a minute.'
  });
