let txt = '';

try {
  txt = r.candidates[0].content.parts
    .map(x => x.text || '')
    .join('');
} catch (e) {
  return out({
    intent: 'help',
    reply: 'I could not read that image. Send a clearer photo. ' + typeIt
  });
}

const m = txt.match(/\{[\s\S]*\}/);
let a;

try {
  a = JSON.parse(m ? m[0] : txt);
} catch (e) {
  return out({
    intent: 'help',
    reply: 'I could not read that image. Send a clearer photo. ' + typeIt
  });
}

if (!a || a.is_receipt === false) {
  return out({
    intent: 'help',
    reply: 'That does not look like a receipt or invoice. ' + typeIt
  });
}

const total = Number(a.total);

if (!(Number.isFinite(total) && total > 0 && total <= 10000000)) {
  return out({
    intent: 'help',
    reply: 'I could not find a clear total on this receipt. ' + typeIt
  });
}

const CATS = [
  'food',
  'transport',
  'rent',
  'utilities',
  'healthcare',
  'education',
  'entertainment',
  'shopping',
  'other'
];

const num = (v) => {
  const n = Number(v);

  return (
    v !== null &&
    v !== undefined &&
    v !== '' &&
    Number.isFinite(n) &&
    n >= 0 &&
    n <= 10000000
  ) ? n.toFixed(2) : null;
};

const cur =
  typeof a.currency === 'string' &&
  /^[A-Za-z]{3}$/.test(a.currency.trim())
    ? a.currency.trim().toUpperCase()
    : null;

