  action: 'receipt_stage',
  merchant: String(a.merchant || '').slice(0, 60),
  date: typeof a.date === 'string' &&
        /^\d{4}-\d{2}-\d{2}$/.test(a.date)
    ? a.date
    : null,
  currency: cur,
  total: total.toFixed(2),
  subtotal: num(a.subtotal),
  tax: num(a.tax),
  category: CATS.includes(a.category) ? a.category : 'other',
  confidence: ['high', 'medium', 'low'].includes(a.confidence)
