    : 'low'
};

// Final check before allowing a database route.
if (p.service_error === true || !uuidPattern.test(userId)) {
  return out({
    intent: 'help',
    reply: 'Your session could not be verified. Nothing was saved. Please try again.'
  });
}

return out({
  user_id: userId,
  needs_db: true,
  action,
  intent: 'receipt_stage'
});

