const FIELDS = { create_semester: ['amount', 'currency', 'due_in_days', 'due_date', 'institution', 'semester'], semester_paid: ['amount', 'currency'], set_daily_budget: ['amount'], set_monthly_budget: ['amount'], set_medical_budget: ['amount'], set_balance: ['amount', 'currency'], create_debt: ['direction', 'counterparty', 'amount', 'currency', 'due_in_days', 'due_date'], repay_debt: ['counterparty', 'amount'] };
