const pick = (n) => { try { const it = $(n).first(); return (it && it.json) ? it.json : null; } catch (e) { return null; } };
const p = pick('Parse') || {};
let r = $input.first().json;
if (Array.isArray(r)) r = r[0];
r = r || {};
const op = (p.pending_op || {}).op;
const out = (o) => [{ json: { ...p, needs_db: false, action: null, ...o, route: o.needs_db ? 'db' : 'static' } }];

if (r.ok !== true) {
  const e = typeof r.error === 'string' ? r.error : '';
  if (op === 'upsert') {
    return out(e === 'stale_state'
      ? { intent: 'clarify', reply: 'That reply no longer matches the current request (it was already handled, changed or expired). Nothing was saved. Please check the latest message or start again.' }
      : { intent: 'clarify', reply: 'I could not save your unfinished request, so nothing was recorded. Please send the full request in one message, for example: "semester fee 2000 BDT due in 10 days".' });
  }
  if (op === 'claim') {
    return out({ intent: 'help', reply: e === 'not_found_or_stale'
      ? 'This confirmation is no longer valid (it expired, was already used or was replaced). Nothing was saved.'
      : 'I could not confirm because the state service had a problem. Nothing was saved. Please try /confirm again in a moment.' });
  }
  if (op === 'cancel') return out({ intent: 'help', reply: 'I could not cancel the pending request right now. Nothing was saved. Please try /cancel again.' });
  return out({ intent: 'help', reply: 'Something went wrong. Nothing was saved.' });
}
if (op === 'upsert') return out({ intent: 'clarify', reply: String(p.pending_reply || 'Please continue.').slice(0, 3000) });
if (op === 'cancel') return out({ intent: 'help', reply: r.cancelled === false ? 'There was nothing pending. Nothing was saved.' : String(p.pending_reply || 'Cancelled. Nothing was saved.') });
if (op === 'claim') {
  const ex = p.pending_exec;
  if (!ex || !ex.action) return out({ intent: 'help', reply: 'Something went wrong. Nothing was saved.' });
  return out({ needs_db: true, action: ex.action, intent: ex.intent, pending_claimed: true, reply: null });
}
return out({ intent: 'help', reply: 'Something went wrong. Nothing was saved.' });
